<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {markets,path,fmt} from '../data'
import {session,openModal} from '../session'
import Coin from '../components/Coin.vue'
import {t} from '../i18n'
import Icon from '../components/Icon.vue'
const route=useRoute(),account=ref("assets.tabs.funding"),hidden=ref(false),currency=ref('USDT'),from=ref("assets.tabs.funding"),to=ref("assets.tabs.trading"),amount=ref(''),message=ref('')
const section=computed(()=>route.params.section||''),balance=computed(()=>session.mode==="common.demo.demo"?100000:0)
function transfer(){message.value='';if(from.value===to.value){message.value="assets.ui.chooseDifferentSourceAndDestinationAccounts";return}if(!Number(amount.value)||Number(amount.value)<=0){message.value="aiQuant.quantFund.subscribe.errorAmountInvalid";return}if(Number(amount.value)>balance.value){message.value="assets.ui.insufficientBalanceSwitchToTheDemoAccount";return}session.orders.push({name:t('assets.transferRecord',{from:t(from.value),to:t(to.value)}),amount:amount.value,symbol:currency.value});amount.value='';message.value="assets.ui.demoTransferCompletedAndAddedToRecords"}
</script>
<template><div class="page-wrap assets-page"><template v-if="!section"><div class="setup-banner"><strong>{{ $t("assets.onboarding.title") }}<span class="positive">1/3</span></strong><span>{{ $t("assets.onboarding.steps.register") }}</span><RouterLink :to="path('/kyc')">{{ $t("assets.onboarding.steps.kyc") }}</RouterLink><span>{{ $t("assets.onboarding.steps.deposit") }}</span><RouterLink class="primary-button" :to="path('/deposit')">{{ $t("assets.onboarding.depositCta") }}</RouterLink></div><section class="card account-overview"><div class="summary-line"><span>{{ $t("assets.totalAssets") }}<button class="icon-button" :aria-label="$t(&quot;common.assetsMenu.hideBalance&quot;)" :aria-pressed="hidden" @click="hidden=!hidden">◉</button></span><span class="tag-chip">{{ $t(session.mode) }}{{ $t("profile.groupAccount") }}</span></div><div class="asset-total">{{ $t(hidden?'••••••':fmt(balance)) }}<small>{{ $t(" .00 USDT") }}</small></div><div class="asset-actions"><RouterLink :to="path('/deposit')"><Icon name="wallet" green/>{{ $t("assets.deposit") }}</RouterLink><RouterLink :to="path('/withdraw')"><Icon name="arrow-right"/>{{ $t("assets.typeWithdraw") }}</RouterLink><button @click="openModal('convert',&quot;assets.convert.title&quot;,{symbol:'USDT',name:'USDT → USDC',min:1})"><Icon name="coins"/>{{ $t("assets.convert.title") }}</button><RouterLink :to="path('/assets/transfer')"><Icon name="trending-up-down"/>{{ $t("assets.transfer") }}</RouterLink><RouterLink :to="path('/assets/records')"><Icon name="layers"/>{{ $t("assets.history") }}</RouterLink></div></section><div class="asset-grid"><aside class="card"><div class="summary-line"><h2>{{ $t("assets.distribution.title") }}</h2><span class="mini-label">{{ $t("USDT") }}</span></div><div class="asset-distribution"><div class="donut"><strong>{{ $t(hidden?'••••':fmt(balance)) }}</strong><span class="mini-label">{{ $t("assets.totalAssets") }}</span></div></div><div class="summary-line"><span class="muted">{{ $t("assets.todayProfit") }}</span><span class="positive">0.00 (0.00%)</span></div><div class="section-gap"><button v-for="a in [&quot;assets.tabs.funding&quot;,&quot;assets.tabs.trading&quot;,&quot;assets.distribution.earnAccount&quot;,&quot;assets.distribution.quantFundAccount&quot;]" :key="a" class="asset-account-button" :class="{active:account===a}" @click="account=a"><span>{{ $t(a) }}</span><span>{{ $t(hidden?'••••':a==="assets.tabs.funding"?fmt(balance):'0.00') }} <small>{{ $t("USDT") }}</small></span></button></div></aside><section class="card"><div class="summary-line"><h2>{{ $t(account) }}{{ $t("assets.ui.details") }}</h2><span class="mini-label">{{ $t("assets.ui.assetAvailableBalance") }}</span></div><div v-for="m in [...markets.filter(m=>['BTC','ETH','SOL','XRP'].includes(m.symbol)),{symbol:'USDT'},{symbol:'USDC'},{symbol:'DAI'}]" :key="m.symbol" class="asset-coin"><span class="coin-label"><Coin :symbol="m.symbol"/>{{ $t(m.symbol) }}</span><span>{{ $t(hidden?'••••':m.symbol==='USDT'&&account==="assets.tabs.funding"?fmt(balance):'0.00') }}<small class="mini-label">≈ {{ $t(hidden?'••••':'0.00') }}{{ $t(" USDT") }}</small></span></div></section></div></template><template v-else-if="section==='transfer'"><div class="form-page"><RouterLink :to="path('/assets')" class="muted">{{ $t("assets.ui.backToAssets") }}</RouterLink><h1>{{ $t("assets.transfer") }}</h1><form class="card form-stack" @submit.prevent="transfer"><label>{{ $t("assets.detail.symbol") }}<select v-model="currency"><option :value="&quot;USDT&quot;">{{ $t("USDT") }}</option><option :value="&quot;BTC&quot;">{{ $t("BTC") }}</option><option :value="&quot;ETH&quot;">{{ $t("ETH") }}</option></select></label><label>{{ $t("home.products.titleFrom") }}<select v-model="from"><option :value="&quot;assets.tabs.funding&quot;">{{ $t("assets.tabs.funding") }}</option><option :value="&quot;assets.tabs.trading&quot;">{{ $t("assets.tabs.trading") }}</option></select></label><button class="green-link" type="button" @click="[from,to]=[to,from]">{{ $t("assets.ui.swapDirection") }}</button><label>{{ $t("home.products.titleTo") }}<select v-model="to"><option :value="&quot;assets.tabs.trading&quot;">{{ $t("assets.tabs.trading") }}</option><option :value="&quot;assets.tabs.funding&quot;">{{ $t("assets.tabs.funding") }}</option></select></label><label>{{ $t("assets.ui.transferAmount") }}<input v-model="amount" inputmode="decimal" :placeholder="$t(&quot;c2c.order.assetAmountPlaceholder&quot;)"/></label><div class="summary-line mini-label"><span>{{ $t("assets.detail.available") }}{{ $t(fmt(balance)) }} {{ $t(currency) }}</span><button type="button" class="green-link" @click="amount=String(balance)">{{ $t("aiQuant.templates.filterAll") }}</button></div><p v-if="message" role="status" :class="message==='assets.ui.demoTransferCompletedAndAddedToRecords'?'form-success':'form-error'">{{ $t(message) }}</p><button class="primary-button">{{ $t("assets.confirmTransfer") }}</button><p class="mini-label">{{ $t("assets.ui.localDemoRecordsNoRealFundsAreTransferred") }}</p></form></div></template><template v-else><RouterLink :to="path('/assets')" class="muted">{{ $t("assets.ui.backToAssets") }}</RouterLink><h1 class="page-title">{{ $t("assets.fundRecords") }}</h1><div class="card"><div class="record-tabs"><button class="active">{{ $t("assets.ui.allRecords") }}</button></div><div v-if="!session.orders.length" class="empty"><Icon name="layers"/>{{ $t("assets.ui.noRecordsYet") }}</div><div v-for="(o,i) in session.orders" :key="i" class="asset-coin"><span>{{ $t(o.name) }}</span><span>{{ $t(o.amount) }} {{ $t(o.symbol) }}<small class="positive">{{ $t("assets.statusCompleted") }}</small></span></div></div></template></div></template>
<style scoped>.donut{border:12px solid #ffffff0b;width:160px;height:160px;border-radius:50%;display:flex;flex-direction:column;justify-content:center;gap:10px}.donut strong{font-size:1.5rem}.asset-coin{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px 0;border-bottom:1px solid #ffffff0a}.asset-coin>span:last-child{text-align:right}.asset-coin small{display:block;margin-top:6px}.asset-account-button small{font-size:0.625rem;color:#fff6}
</style>
